let standaloneMode=!String(location.hostname||'').endsWith('.chatgpt.site');
let accountUser=null,accountEtag=null,accountLoaded=false,accountSaving=false,accountDirty=false,accountTimer,accountError='',accountCloud=null,accountGeneration=0;
async function accountFetch(url,options={}){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);try{return await fetch(url,{...options,signal:controller.signal})}finally{clearTimeout(timer)}}
function accountHeaders(){return {'Content-Type':'application/json','X-Camino-Request':'workspace','If-Match':accountEtag||'new'}}
async function bootstrapAccount(){try{const me=await accountFetch('/api/me',{cache:'no-store'});if(!me.ok){AcademicPathway.normalizeState(state);accountLoaded=true;render();return}const data=await me.json();if(data.standalone){standaloneMode=true;AcademicPathway.normalizeState(state);accountLoaded=true;render();return}standaloneMode=false;accountUser=data.user;if(!data.storageReady)throw Error('Account storage is temporarily unavailable. Your local records are preserved.');const res=await accountFetch('/api/workspace',{cache:'no-store'});if(!res.ok)throw Error('Could not load your account.');const cloud=await res.json();const upgrade=cloud.state&&cloud.state.academicSchema!==1;accountEtag=cloud.etag;accountCloud=cloud.state;if(cloud.state){state=WorkspaceSchema.validate(cloud.state);state.courses||=[];state.tasks||={};state.scenarios||=[];state.historyDone||=state.courses.length>0;const clean=E.consolidate(state.courses.map(TranscriptImport.repairLegacyCourse));state.courses=clean.courses;state.excludedAttempts=[...(state.excludedAttempts||[]),...clean.excluded];mode=state.profile?.load||'Accelerated';}else{state={courses:[],tasks:{},scenarios:[]};mode='Accelerated';}let pending=null;try{pending=JSON.parse(localStorage.getItem('camino-pending-'+accountUser.email)||'null')}catch{}if(pending){state=WorkspaceSchema.validate(pending.state);mode=state.profile?.load||'Balanced';accountEtag=pending.etag;accountDirty=true;accountError='Unsynced changes restored from this browser. Retry sync or export a backup; a conflicting server copy will not be overwritten.';}AcademicPathway.normalizeState(state);accountLoaded=true;if(upgrade)save();render();}catch(e){accountError=e.message;if(accountUser){try{const cache=localStorage.getItem('camino-account-'+accountUser.email);if(cache){state=WorkspaceSchema.validate(JSON.parse(cache));mode=state.profile?.load||'Balanced';accountDirty=true;}}catch{}}AcademicPathway.normalizeState(state);accountLoaded=true;render();}}
function scheduleAccountSave(){if(!accountUser||!accountLoaded)return;accountDirty=true;try{localStorage.setItem('camino-pending-'+accountUser.email,JSON.stringify({etag:accountEtag,state}))}catch{}if(accountError)return;clearTimeout(accountTimer);accountTimer=setTimeout(flushAccount,500)}
async function flushAccount(){if(!accountDirty||accountSaving||!accountUser||accountError)return;accountSaving=true;accountDirty=false;const generation=accountGeneration;try{const res=await accountFetch('/api/workspace',{method:'PUT',headers:accountHeaders(),body:JSON.stringify(WorkspaceSchema.validate(state))});const data=await res.json();if(!res.ok)throw Error(data.error||'Account save failed');if(generation===accountGeneration){accountEtag=data.etag;accountCloud=JSON.parse(JSON.stringify(state));localStorage.removeItem('camino-pending-'+accountUser.email);}}catch(e){accountDirty=true;accountError=e.message;toast('Account sync paused: '+accountError)}finally{accountSaving=false;if(accountDirty&&!accountError)flushAccount();const badge=document.querySelector('#sync-status');if(badge)badge.textContent=accountError?'Sync paused':accountDirty?'Saving…':'Saved to your account';}}
function accountPage(){if(standaloneMode)return page('YOUR CAMINO WORKSPACE','Your plan, on your device.',`<div class="card form-wrap"><h2>No sign-in needed.</h2><p>Account creation, login and cross-device sync are not configured on this standalone deployment. No sign-in is needed for local planning.</p><p>Your reviewed courses and goals are saved in this browser. Export a backup to move them between devices or from the original Camino site.</p><button class="btn" id="export-workspace">Export workspace ↓</button><label>Restore a Camino workspace backup<input type="file" id="restore-workspace" accept="application/json,.json"></label><p>Restoring replaces this browser’s current workspace after confirmation.</p><p><button class="btn" id="delete-all-data">Delete all my data / start fresh</button></p></div>`);return page('YOUR CAMINO ACCOUNT','Your future, saved.',`${accountUser?`<div class="card form-wrap"><span class="tag">SIGNED IN WITH CHATGPT</span><h2>${esc(accountUser.name||accountUser.email||'Your account')}</h2><p id="sync-status">${accountError?esc(accountError):'Reviewed courses and plans are saved privately to your account.'}</p>${accountError?'<button class="btn" id="retry-account">Retry saved workspace sync</button>':''}<div class="actions"><a class="btn" href="/signout-with-chatgpt?return_to=%2F%23account" target="_top">Sign out ↗</a><button class="btn" id="account-save">Save current workspace now</button></div><p>Original transcript files and raw extracted text are never stored in your account. You can export or delete your saved workspace in Privacy & data.</p>${!accountCloud&&localStorage.getItem('camino-v1')?'<button class="btn primary" id="migrate-local">Import this browser’s earlier workspace</button>':''}</div>`:`<div class="card form-wrap"><span class="tag">ONE ACCOUNT. YOUR WHOLE JOURNEY.</span><h2>Pick up where you left off.</h2><p>Continue with ChatGPT to create your Camino account and save reviewed courses, goals, and plans across devices. No separate password to remember.</p><a class="btn primary" href="/signin-with-chatgpt?return_to=%2F%23history" target="_top">Create account / sign in with ChatGPT ↗</a><p>You can also explore without an account. Guest records remain in this browser.</p></div>`}`)}
function accountBanner(){if(standaloneMode)return `<div class="account-banner"><span>Saved in this browser · No sign-in required</span><a href="#account">Back up / restore ↗</a></div>`;return `<div class="account-banner"><span>${!accountLoaded?'Connecting to your account…':accountUser?accountError?'Account sync paused':`Signed in · ${esc(accountUser.name||accountUser.email||'Your account')}`:'Save your journey across devices.'}</span><a href="#account">${accountUser?'My account ↗':'Create account / Sign in ↗'}</a></div>`}
function bindAccount(){
 document.querySelector('#delete-all-data')?.addEventListener('click',deleteWorkspace);
 document.querySelector('#export-workspace')?.addEventListener('click',()=>download('camino-workspace.json',JSON.stringify(state,null,2)));
 document.querySelector('#restore-workspace')?.addEventListener('change',async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>2000000)throw Error('Workspace must be under 2 MB.');const imported=JSON.parse(await file.text());if(!imported||!Array.isArray(imported.courses)||imported.courses.length>2000||imported.courses.some(c=>!c||typeof c.code!=='string'||typeof c.title!=='string'||!Number.isFinite(+c.credits)))throw Error('Choose a valid Camino workspace backup.');if(!confirm('Replace the workspace in this browser with this backup?'))return;state=imported;state.tasks||={};state.scenarios||=[];state.historyDone||=state.courses.length>0;AcademicPathway.normalizeState(state);mode=state.profile?.load||'Balanced';save();location.hash='roadmap';render();toast('Workspace restored.')}catch(err){toast(err.message)}});
document.querySelector('#account-save')?.addEventListener('click',async()=>{if(accountError)return toast(accountError);scheduleAccountSave();clearTimeout(accountTimer);await flushAccount();if(!accountError)toast('Workspace saved to your account.')});document.querySelector('#retry-account')?.addEventListener('click',()=>location.reload());document.querySelector('#migrate-local')?.addEventListener('click',()=>{if(!confirm('Copy this browser’s earlier workspace into your account?'))return;try{const previous=JSON.parse(localStorage.getItem('camino-v1'));if(!previous)return;state=previous;state.courses=E.consolidate((state.courses||[]).map(TranscriptImport.repairLegacyCourse)).courses;state.tasks||={};state.scenarios||=[];state.historyDone=state.courses.length>0;save();render();toast('Earlier workspace copied to your account.')}catch{toast('Could not import that workspace.')}})}

// A wipe in another tab invalidates in-memory records here before another save.
window.addEventListener('storage',event=>{if(event.key==='camino-wipe-event'&&event.newValue){if(typeof ReviewSession!=='undefined')ReviewSession.clear();clearTimeout(accountTimer);accountDirty=false;accountGeneration++;try{for(const key of Object.keys(sessionStorage))if(key.startsWith('camino-'))sessionStorage.removeItem(key)}catch{}if(typeof essayRequestController!=='undefined')essayRequestController?.abort();location.reload();}});
